function siteCard(s){return `<article class="site-card"><a class="site-main" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" title="${esc(s.name)} · 在新标签页打开"><span class="site-symbol tone-${esc(s.tone||'blue')}" aria-hidden="true">${s.icon_url?`<img src="${esc(s.icon_url)}" alt="" class="site-icon" loading="lazy">`:`<span title="暂无站点图标">${esc(s.monogram||s.name[0])}</span>`}</span><div class="site-copy"><strong>${esc(s.name)} ${s.api?'<span class="api-badge">API</span>':''}</strong><p>${esc(s.description||s.category)}</p></div><span class="site-arrow" aria-hidden="true">↗</span></a><button class="site-favorite mini" data-action="site-favorite" data-id="${esc(s.id)}" data-enabled="${!s.favorite}" aria-label="${s.favorite?'取消收藏':'收藏'}网站：${esc(s.name)}">${s.favorite?'★':'☆'}</button></article>`}
function siteGroups(){const categories=S.site_categories.filter(c=>!siteCategory||c.id===siteCategory);const groups=categories.map(c=>{const items=siteEntries().filter(s=>s.group===c.id&&siteMatches(s));return items.length?`<section class="directory-group"><div class="section-head"><h2>${esc(c.name)}</h2><small>${esc(c.hint)}</small></div><div class="site-grid">${items.map(siteCard).join('')}</div></section>`:''}).join('');return groups||'<div class="empty block">没有匹配的渠道。可以切换到“全部渠道”，换个关键词，或直接把其他网站的资料链接添加到下方。</div>'}
