if(a==='material-fullscreen'){const scope=el.dataset.scope,full='full:'+scope.replace(/^full:/,''),items=materialsFor(scope),choice=viewerOptions(scope);const shown=choice.all?items:items.filter(x=>x.group===(choice.group||items[0]?.group));const selected=shown.find(x=>x.key===choice.key)||shown[0];if(!selected)return;materialChoices.set(full,{key:selected.key});modal('材料预览',renderMaterialViewer(full,items,{all:true,key:selected.key}));$('#modal').classList.add('material-fullscreen');return}
if(a==='script-edit'){const section=document.querySelector(`[data-script-page="${CSS.escape(el.dataset.page)}"]`),input=section.querySelector('textarea');input.value=[...section.querySelectorAll('[data-script-paragraph]')].map(p=>p.textContent).join('\n\n');syncStoryboardEditors();input.focus();markFormChanges();return}
if(a==='close'){if(document.fullscreenElement)await document.exitFullscreen();$('#modal').close();presentation=null;return}if(a==='reload'){await reload();toast('已载入最新版本');return}
if(a==='toggle-nav'){const opened=document.body.classList.toggle('mobile-nav-open');el.setAttribute('aria-expanded',String(opened));el.setAttribute('aria-label',opened?'收起导航':'展开导航');return}
if(a==='stage'){const st=S.progress.find(x=>x.id===el.dataset.stage);if(!st?.accessible){toast('请先完成前序阶段与 Agent 审核');return}location.hash=st.id;return}
if(a==='collapse-nav'){const hidden=document.body.classList.toggle('sidebar-hidden');localStorage.setItem('mediagen-sidebar-hidden',String(hidden));el.setAttribute('aria-expanded',String(!hidden));el.setAttribute('aria-label',hidden?'展开左侧导航':'收起左侧导航');return}
if(a==='copy-handoff'){const text=`请读取当前 mediagen 项目 ${S.project}（v${S.revision}）的最新选择、购物车和图片批注，针对“${viewNames[el.dataset.stage]}”说明修改影响、保留内容和待确认事项，完成独立审核；不要自动付费生成。`;try{await navigator.clipboard.writeText(text);toast('已复制，回到 Codex 粘贴即可')}catch{modal('回到 Codex 对齐',`<p>${esc(text)}</p>`)}return}
if(a==='source-preview'){const r=await api('/api/v3/content-sources/'+encodeURIComponent(el.dataset.id)+'/preview');r.note=document.getElementById('source-note-'+el.dataset.id)?.value??(S.content_sources||[]).find(x=>x.id===el.dataset.id)?.note;modal('内容底稿 · '+r.title,paragraphPreview(r));return}
if(a==='page-evidence'){const r=await api('/api/v3/pages/'+encodeURIComponent(el.dataset.page)+'/evidence/'+encodeURIComponent(el.dataset.index));modal('支撑材料 · '+r.title,paragraphPreview(r));return}
if(a==='reference-deck-preview'){const r=await api('/api/v3/reference-decks/'+encodeURIComponent(el.dataset.id)+'/preview');r.note=document.getElementById('source-note-'+el.dataset.id)?.value??(S.reference_decks||[]).find(x=>x.id===el.dataset.id)?.note??r.note;const number=Number(el.dataset.startPage||(el.dataset.pages||'').split(',')[0]||0);referenceDeckPreview=r;renderReferenceDeck(Math.max(0,r.pages.findIndex(p=>p.number===number)));return}
if(a==='reference-deck-page'){renderReferenceDeck(Number(el.dataset.index));return}
if(a==='source-info'){const isDeck=(S.reference_decks||[]).some(x=>x.id===el.dataset.id),r=[...(S.content_sources||[]),...(S.reference_decks||[])].find(x=>x.id===el.dataset.id);if(!r)throw Error('来源记录已变化，请刷新后查看');modal('来源信息',`<p class="source-preview-note">${esc(r.original_name||r.title)}</p><dl class="value-detail source-info-list"><div><dt>溯源编号</dt><dd><code>${esc(r.id)}</code></dd></div><div><dt>固定版本</dt><dd><code>${esc(r.version||'待记录')}</code></dd></div><div><dt>引用方式</dt><dd>${isDeck?'来源编号 / 源第 N 页 · 保留原文件页序':'来源编号 / para-NNN · 沿用原段落编号'}</dd></div><div><dt>用途</dt><dd>${esc(r.use||'本次汇报的内容底稿')}</dd></div>${r.note?`<div><dt>备注</dt><dd>${esc(r.note)}</dd></div>`:''}${isDeck&&r.related_source_id?`<div><dt>配套讲稿</dt><dd>${esc((S.content_sources||[]).find(x=>x.id===r.related_source_id)?.original_name||r.related_source_id)}</dd></div>`:''}</dl>`);return}
if(a==='site-favorite'){await api('/api/v3/sites/favorite',{id:el.dataset.id,enabled:el.dataset.enabled==='true'});await reload();toast('精选收藏已更新，未改变购物车');return}
if(a==='annotate-reference'){await startReferenceAnnotation(el.dataset.id);return}
if(a==='present-reference'){await present(el.dataset.deck);return}
if(a==='present-project'){await present('');return}
if(a==='present-prev'||a==='present-next'||a==='present-jump'){presentation.index=a==='present-jump'?Number(el.dataset.index):Math.max(0,Math.min(presentation.pages.length-1,presentation.index+(a==='present-next'?1:-1)));renderPresentation();return}
if(a==='fullscreen'){const full=document.body.classList.toggle('presentation-fullscreen');el.textContent=full?'退出全屏':'全屏播放';if(full){try{await document.documentElement.requestFullscreen()}catch{toast('已进入窗口内全屏；浏览器未允许系统全屏，可按 F11 隐藏浏览器栏。')}}else if(document.fullscreenElement)await document.exitFullscreen();return}
