if(a==='search'){filter={...filter,q:$('#search-assets').value,kind:$('#filter-kind').value,work:$('#filter-work').value,favorite:$('#filter-favorite').checked,distinct:!!$('#filter-distinct')?.checked};for(const e of document.querySelectorAll('[data-facet]'))filter[e.dataset.facet]=e.value;await renderView();return}
if(a==='asset-family'){filter={q:filter.q,family:el.dataset.family,kind:'',work:'',favorite:filter.favorite,archived:filter.archived,distinct:filter.distinct};await renderView();return}
if(a==='asset-archive-view'){filter={q:'',family:'',kind:'',work:'',favorite:false,archived:!filter.archived,distinct:filter.distinct};await renderView();return}
