if(a==='asset-remove'){const r=await api(`/api/v3/assets/${encodeURIComponent(el.dataset.id)}?version=${encodeURIComponent(el.dataset.version)}`);modal('移除这份素材？',`<div class="asset-removal-confirm"><img src="${esc(r.preview_url)}" alt="${esc(r.title)}"><div><h3>${esc(r.title)}</h3><p>移除后不再出现在素材库、精选和新的参考推荐中。</p><p class="muted">不会删除本机原文件，也不会改变项目已经选用的版本。需要时，可在「已移除」中恢复。</p></div></div><div class="actions"><button data-action="cancel-asset-remove">保留素材</button><button class="asset-remove-confirm" data-action="confirm-asset-remove" data-id="${esc(r.id)}" data-version="${esc(r.version)}">确认移除</button></div>`);return}
if(a==='cancel-asset-remove'){$('#modal').close();return}
if(a==='confirm-asset-remove'||a==='asset-restore'){el.disabled=true;try{const archived=a==='confirm-asset-remove';await api('/api/v3/assets/visibility',{id:el.dataset.id,version:el.dataset.version,archived});if(archived){checked.delete(el.dataset.id);selectedVersions.delete(el.dataset.id)}$('#modal').close();await reload(false);await renderView();toast(archived?'已移除，可在「已移除」中恢复。原文件与项目选用版本未改变。':'已恢复到素材库')}finally{el.disabled=false}return}
if(a==='choose'||a==='add-checked'){const ids=a==='choose'?[el.dataset.id]:[...checked];for(const id of ids){await api('/api/v3/cart/choose',{id,version:(currentPreview?.id===id&&$('#modal').open?currentPreview.version:null)||selectedVersions.get(id)||listing?.items.find(x=>x.id===id)?.version,usage:$('#preview-usage')?.value||'structure'});await reload(false);checked.delete(id)}$('#modal').close();await renderView();toast(`已将 ${ids.length} 项加入购物车，尚未用于生成`);return}
